```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::inference_llm;

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

fn truncate(mut s: String, max: usize) -> String {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while end > 0 && !s.is_char_boundary(end) {
        end -= 1;
    }
    s.truncate(end);
    s
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        // Enrichment fetch: the result is deliberately ignored so the output
        // is unchanged whether it succeeds or fails.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&info.date)
        );
        let _ = http_client::fetch(&url);

        let mut prompt = String::new();
        for e in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str(&format!("- {}: {}\n", e.title, e.summary));
        }

        let system = "Write a short overview paragraph (under 500 characters) for a daily digest of the listed items.";
        let reply = inference_llm::infer(system, &prompt, "digest");
        let mut overview = truncate(reply.trim().to_string(), 600);
        if overview.is_empty() {
            overview = format!("{} items in today's digest.", selected.entries.len());
        }

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
```

Selection and RunInfo have no free-text field, so I used `info.date` as the `q` value, percent-encoded. The fetch uses `fetch` rather than `get`, and its result is discarded. A transport failure therefore can't change the digest.

